function sum(a, b) {
  console.log(this.n + a + b);
}
const step = sum.bind({ n: 1 }, 2).bind({ n: 9 }, 3);
step(4);

const box = {
  n: 1,
  run() {
    const read = () => console.log(this.n);
    read.call({ n: 2 });
    read.apply({ n: 3 });
  },
};
box.run();

function ObjectBox() {
  this.n = 1;
  return { n: 2 };
}
function PrimitiveBox() {
  this.n = 1;
  return 3;
}
console.log(new ObjectBox().n);
console.log(new PrimitiveBox().n);

function show() {
  'use strict';
  if (this == null) {
    console.log(1);
    return;
  }
  console.log(this + 2);
}
show.call(null);
show.call(3);

const box = {
  n: 1,
  get next() {
    return this.n + 1;
  },
};
console.log(box.next);
const getNext = Object.getOwnPropertyDescriptor(box, 'next').get;
console.log(getNext.call({ n: 4 }));

function add(extra = this.n) {
  console.log(this.n + extra);
}
add.call({ n: 1 });
add.call({ n: 2 }, 3);

function show(extra) {
  console.log(this.n + extra);
}
Function.prototype.call.call(show, { n: 1 }, 2);
Reflect.apply(show, { n: 4 }, [5]);

function Box(n) {
  if (!new.target) {
    console.log(1);
    return;
  }
  this.n = n;
  console.log(this.n + 1);
}
Box(0);
new Box(2);

class Box {
  static n = 1;
  static show() {
    console.log(this.n);
  }
}
Box.show();
const show = Box.show;
try {
  show();
} catch {
  console.log(2);
}

class Box {
  constructor(n) {
    this.n = n;
  }
}
try {
  Box.call({ n: 1 });
  console.log(1);
} catch {
  console.log(2);
}
console.log(new Box(3).n);

function Name(n) {
  this.n = n;
}
function Extra(x) {
  this.x = x;
}
function Pair(n, x) {
  Name.call(this, n);
  Extra.call(this, x);
  console.log(this.n + this.x);
}
new Pair(1, 2);

const proto = {
  n: 1,
  get next() {
    return this.n + 1;
  },
};
const box = Object.create(proto);
box.n = 4;
console.log(box.next);
console.log(proto.next);

class Box {
  #n = 1;
  read() {
    console.log(this.#n);
  }
}
const box = new Box();
box.read();
const read = box.read;
try {
  read.call({ n: 2 });
} catch {
  console.log(4);
}

class Base {
  n = 1;
  show() {
    console.log(this.n);
  }
}
class Child extends Base {
  n = 2;
  run() {
    const go = () => super.show();
    go.call({ n: 9 });
  }
}
new Child().run();

class Base {
  constructor() {
    this.n = 1;
    console.log(this.n);
  }
}
class Child extends Base {
  n = 2;
  constructor() {
    super();
    console.log(this.n);
  }
}
new Child();
